    elf:        optValue('--elf', null),
    maxSeconds: parseFloat(optValue('--max-seconds', process.env.VM_MAX_SECONDS || '0')) || 0,
    maxFrames:  parseInt(optValue('--max-frames',   process.env.VM_MAX_FRAMES   || '0'), 10) || 0,
    framesDir:  optValue('--frames-dir', process.env.VM_FRAMES_DIR || ''),
