/* ------------------------------------------------------------------ */
/*  ELF loader                                                         */
/* ------------------------------------------------------------------ */

function loadElf(file) {
    const buf = fs.readFileSync(file);
    if (buf.length < 52 || buf[0] !== 0x7f || buf[1] !== 0x45 ||
        buf[2] !== 0x4c || buf[3] !== 0x46) {
        throw new Error(file + ' is not an ELF file');
    }
    const ei_data = buf[5];
    const e_type  = buf.readUInt16LE(16);
    const e_machine = buf.readUInt16LE(18);
    if (e_machine !== 8) throw new Error('not a MIPS binary (e_machine=' + e_machine + ')');
    if (ei_data !== 1) throw new Error('only little endian MIPS binaries are supported');

    const entry   = buf.readUInt32LE(24);
    const phoff   = buf.readUInt32LE(28);
    const phentsize = buf.readUInt16LE(42);
    const phnum   = buf.readUInt16LE(44);

    let top = 0;
    for (let i = 0; i < phnum; i++) {
        const ph = phoff + i * phentsize;
        const p_type   = buf.readUInt32LE(ph + 0);
        const p_offset = buf.readUInt32LE(ph + 4);
