                ' $' + (i+1) + '=0x' + (R[i+1] >>> 0).toString(16) +
                ' $' + (i+2) + '=0x' + (R[i+2] >>> 0).toString(16) +
                ' $' + (i+3) + '=0x' + (R[i+3] >>> 0).toString(16) + '\n');
        }
        process.stderr.write('[vm] recent pcs: ');
        for (let i = 0; i < 16; i++) {
            process.stderr.write('0x' + (lastPcs[(lastPcIdx + i) & 15] >>> 0).toString(16) + ' ');
        }
        process.stderr.write('\n');
    }
    shutdown(1);
}

function defaultFramesDir() {
    return path.join(process.cwd(), 'frames');
}

function shutdown(code) {
    flushAllFds();
    const secs = (Date.now() - startTime) / 1000;
    process.stderr.write('[vm] finished after ' + (instrCount / 1e6).toFixed(1) +
        'M instructions (' + secs.toFixed(1) + 's, ' +
        Math.round(instrCount / Math.max(secs, 0.001) / 1e6) + 'M instr/s), ' +
        framesSaved + ' frame(s) saved\n');
    if (OPT.framesDir && frameCounter > 0) {
        process.stderr.write('[vm] frame copies in ' + OPT.framesDir + '\n');
    }
    try { process.exit(code & 0xff); } catch (e) { }
}

process.on('SIGINT', () => { process.stderr.write('\n[vm] interrupted\n'); shutdown(130); });
process.on('SIGTERM', () => { shutdown(143); });

/* ------------------------------------------------------------------ */
/*  main loop                                                          */
/* ------------------------------------------------------------------ */

const startTime = Date.now();
let lastReport = startTime;

function run(entry) {
    PC = entry;
    NEXT_PC = (PC + 4) | 0;

    const M = mem;
    const r = R;
    const fuL = fu, ffL = ff, fwL = fw, fccL = fcc;

    let icnt = 0;
    let nextCheck = 1 << 20;

    for (;;) {
        /* ---------------- instruction fetch ---------------- */
        const pc = PC;
        const inst = (M[pc] | (M[pc + 1] << 8) | (M[pc + 2] << 16) | (M[pc + 3] << 24)) | 0;
        PC = NEXT_PC;
        NEXT_PC = (PC + 4) | 0;

        lastPcs[lastPcIdx] = pc;
        lastPcIdx = (lastPcIdx + 1) & 15;
        icnt++;

        const op = inst >>> 26;
        const rs = (inst >>> 21) & 31;
        const rt = (inst >>> 16) & 31;
        const imm = inst & 0xffff;
        const simm = (imm << 16) >> 16;

        switch (op) {

        /* ============================================================ */
        /* SPECIAL                                                      */
        /* ============================================================ */
        case 0: {
            const rd = (inst >>> 11) & 31;
            const sa = (inst >>> 6) & 31;
            const fn = inst & 63;
            switch (fn) {
            case 0:                                     /* sll / nop */
                r[rd] = r[rt] << sa;
                break;
            case 2:                                     /* srl / ror */
                if (sa & 1) {
                    const v = r[rt], s = sa & 31;
                    r[rd] = (v >>> s) | (v << (32 - s));
                } else {
                    r[rd] = r[rt] >>> sa;
                }
                break;
            case 3:                                     /* sra */
                r[rd] = r[rt] >> sa;
                break;
            case 4:                                     /* sllv */
                r[rd] = r[rt] << (r[rs] & 31);
                break;
            case 6: {                                   /* srlv / rorv */
                const v = r[rt], s = r[rs] & 31;
                if ((inst >>> 6) & 1) r[rd] = (v >>> s) | (v << (32 - s));
                else r[rd] = v >>> s;
                break;
            }
            case 7:                                     /* srav */
                r[rd] = r[rt] >> (r[rs] & 31);
                break;
            case 8:                                     /* jr */
                NEXT_PC = r[rs];
                break;
            case 9: {                                   /* jalr */
                const t = r[rs];
                r[rd] = (pc + 8) | 0;
                NEXT_PC = t;
                break;
            }
            case 10:                                    /* movz */
                if (r[rt] === 0) r[rd] = r[rs];
                break;
            case 11:                                    /* movn */
                if (r[rt] !== 0) r[rd] = r[rs];
                break;
            case 12: {                                  /* syscall */
                const ret = doSyscall(r[2] | 0, r[4] | 0, r[5] | 0, r[6] | 0,
                                      r[7] | 0, r[8] | 0, r[9] | 0);
                r[2] = ret | 0;
                instrCount = icnt;
                if (exited) return;
                break;
            }
            case 13:                                    /* break */
                fault('break instruction', undefined, inst, pc);
                return;
            case 15:                                    /* sync */
                break;
            case 16: r[rd] = HI; break;                 /* mfhi */
            case 17: HI = r[rs]; break;                 /* mthi */
            case 18: r[rd] = LO; break;                 /* mflo */
            case 19: LO = r[rs]; break;                 /* mtlo */
            case 24: {                                  /* mult */
                const p = r[rs] * r[rt];
                LO = p | 0;
                HI = Math.floor(p / 4294967296) | 0;
                break;
            }
            case 25: {                                  /* multu */
                const a = r[rs] >>> 0, b = r[rt] >>> 0;
                const al = a & 0xffff, ah = a >>> 16;
                const bl = b & 0xffff, bh = b >>> 16;
                const ll = al * bl, lh = al * bh, hl = ah * bl, hh = ah * bh;
                const mid = (ll >>> 16) + (lh & 0xffff) + (hl & 0xffff);
                LO = ((ll & 0xffff) | (mid << 16)) | 0;
                HI = (hh + (lh >>> 16) + (hl >>> 16) + (mid >>> 16)) | 0;
                break;
            }
            case 26: {                                  /* div */
                const a = r[rs], b = r[rt];
                if (b !== 0) { LO = (a / b) | 0; HI = (a % b) | 0; }
                else { LO = 0; HI = 0; }
                break;
            }
            case 27: {                                  /* divu */
                const a = r[rs] >>> 0, b = r[rt] >>> 0;
                if (b !== 0) { LO = (a / b) | 0; HI = (a % b) | 0; }
                else { LO = 0; HI = 0; }
                break;
            }
            case 32: case 33:                           /* add / addu */
                r[rd] = (r[rs] + r[rt]) | 0;
                break;
            case 34: case 35:                           /* sub / subu */
                r[rd] = (r[rs] - r[rt]) | 0;
                break;
            case 36: r[rd] = r[rs] & r[rt]; break;      /* and  */
            case 37: r[rd] = r[rs] | r[rt]; break;      /* or   */
            case 38: r[rd] = r[rs] ^ r[rt]; break;      /* xor  */
            case 39: r[rd] = ~(r[rs] | r[rt]) | 0; break; /* nor */
            case 42: r[rd] = r[rs] < r[rt] ? 1 : 0; break;            /* slt  */
            case 43: r[rd] = (r[rs] >>> 0) < (r[rt] >>> 0) ? 1 : 0; break; /* sltu */
            case 52:                                    /* teq */
                if (r[rs] === r[rt]) fault('trap (teq)', undefined, inst, pc);
                break;
            case 54:                                    /* tne */
                break;
            case 1:                                     /* movf/movt (FPU cc) */
            case 11 + 0:
                break;
            default:
                fault('unimplemented SPECIAL funct ' + fn, undefined, inst, pc);
                return;
            }
            break;
        }

        /* ============================================================ */
        /* REGIMM                                                       */
        /* ============================================================ */
        case 1: {
            const t = (PC + (simm << 2)) | 0;
            switch (rt) {
            case 0:  if (r[rs] < 0)  NEXT_PC = t; break;   /* bltz   */
            case 1:  if (r[rs] >= 0) NEXT_PC = t; break;   /* bgez   */
            case 16: if (r[rs] < 0)  { r[31] = (pc + 8) | 0; NEXT_PC = t; } break;
            case 17: if (r[rs] >= 0) { r[31] = (pc + 8) | 0; NEXT_PC = t; } break;
            case 2:  if (r[rs] === 0 && (r[rs] & 1)) NEXT_PC = t; break; /* bltzl */
            case 3:  break;
            case 18: if (r[rs] < 0)  { r[31] = (pc + 8) | 0; NEXT_PC = t; } break; /* bltzal */
            case 19: if (r[rs] >= 0) { r[31] = (pc + 8) | 0; NEXT_PC = t; } break;
            default:
                fault('unimplemented REGIMM rt ' + rt, undefined, inst, pc);
                return;
            }
            break;
        }

        case 2:                                         /* j */
            NEXT_PC = ((pc + 4) & 0xf0000000) | ((inst & 0x3ffffff) << 2);
            break;
        case 3:                                         /* jal */
            r[31] = (pc + 8) | 0;
            NEXT_PC = ((pc + 4) & 0xf0000000) | ((inst & 0x3ffffff) << 2);
            break;
        case 4:                                         /* beq */
            if (r[rs] === r[rt]) NEXT_PC = (PC + (simm << 2)) | 0;
            break;
        case 5:                                         /* bne */
            if (r[rs] !== r[rt]) NEXT_PC = (PC + (simm << 2)) | 0;
            break;
        case 6:                                         /* blez */
            if (r[rs] <= 0) NEXT_PC = (PC + (simm << 2)) | 0;
            break;
        case 7:                                         /* bgtz */
            if (r[rs] > 0) NEXT_PC = (PC + (simm << 2)) | 0;
            break;
        case 20:                                        /* beql */
            if (r[rs] === r[rt]) NEXT_PC = (PC + (simm << 2)) | 0;
            else PC = (PC + 4) | 0, NEXT_PC = (PC + 4) | 0;
            break;
        case 21:                                        /* bnel */
            if (r[rs] !== r[rt]) NEXT_PC = (PC + (simm << 2)) | 0;
            else PC = (PC + 4) | 0, NEXT_PC = (PC + 4) | 0;
            break;
        case 22:                                        /* blezl */
            if (r[rs] <= 0) NEXT_PC = (PC + (simm << 2)) | 0;
            else PC = (PC + 4) | 0, NEXT_PC = (PC + 4) | 0;
            break;
        case 23:                                        /* bgtzl */
            if (r[rs] > 0) NEXT_PC = (PC + (simm << 2)) | 0;
            else PC = (PC + 4) | 0, NEXT_PC = (PC + 4) | 0;
            break;

        /* ============================================================ */
        /* ALU immediate                                                */
        /* ============================================================ */
        case 8: case 9:                                 /* addi(u) */
            r[rt] = (r[rs] + simm) | 0;
            break;
        case 10:                                        /* slti */
            r[rt] = r[rs] < simm ? 1 : 0;
            break;
        case 11:                                        /* sltiu */
            r[rt] = (r[rs] >>> 0) < (simm >>> 0) ? 1 : 0;
            break;
        case 12: r[rt] = r[rs] & imm; break;            /* andi */
        case 13: r[rt] = r[rs] | imm; break;            /* ori  */
        case 14: r[rt] = r[rs] ^ imm; break;            /* xori */
        case 15: r[rt] = (imm << 16) | 0; break;        /* lui  */

        /* ============================================================ */
        /* SPECIAL2                                                     */
        /* ============================================================ */
        case 28: {
            const rd = (inst >>> 11) & 31;
            const fn = inst & 63;
            switch (fn) {
            case 2:                                     /* mul */
                r[rd] = Math.imul(r[rs], r[rt]) | 0;
                break;
            case 0: case 1: {                           /* madd / maddu */
                const acc = ((HI * 4294967296) + (LO >>> 0));
                const p = fn === 0 ? (r[rs] * r[rt]) : ((r[rs] >>> 0) * (r[rt] >>> 0));
                const t = acc + p;
                LO = t | 0;
                HI = Math.floor(t / 4294967296) | 0;
                break;
            }
            case 4: case 5: {                           /* msub / msubu */
                const acc = ((HI * 4294967296) + (LO >>> 0));
                const p = fn === 4 ? (r[rs] * r[rt]) : ((r[rs] >>> 0) * (r[rt] >>> 0));
                const t = acc - p;
                LO = t | 0;
                HI = Math.floor(t / 4294967296) | 0;
                break;
            }
            case 32: {                                  /* clz */
                let v = r[rs] >>> 0, n = 0;
                if (v === 0) n = 32;
                else { while ((v & 0x80000000) === 0) { v <<= 1; n++; } }
                r[rd] = n;
                break;
            }
            case 33: {                                  /* clo */
                let v = (~r[rs]) >>> 0, n = 0;
                if (v === 0) n = 32;
                else { while ((v & 0x80000000) === 0) { v <<= 1; n++; } }
                r[rd] = n;
                break;
            }
            default:
                fault('unimplemented SPECIAL2 funct ' + fn, undefined, inst, pc);
                return;
            }
            break;
        }

        /* ============================================================ */
        /* SPECIAL3 (MIPS32r2)                                          */
        /* ============================================================ */
        case 31: {
            const rd = (inst >>> 11) & 31;
            const sa = (inst >>> 6) & 31;
            const fn = inst & 63;
            switch (fn) {
            case 0: {                                   /* ext */
                const size = sa + 1, pos = rd;
                r[rt] = (r[rs] >>> pos) & ((size >= 32) ? -1 : ((1 << size) - 1));
                break;
            }
            case 4: {                                   /* ins */
                const msb = sa, pos = rd;
                const size = msb - pos + 1;
                const mask = ((size >= 32) ? -1 : ((1 << size) - 1));
                r[rt] = (r[rt] & ~(mask << pos)) | ((r[rs] & mask) << pos);
                break;
            }
            case 32: {                                  /* seb / seh / wsbh */
                const v = r[rt];
                if (sa === 16) r[rd] = (v << 24) >> 24;          /* seb */
                else if (sa === 24) r[rd] = (v << 16) >> 16;     /* seh */
                else if (sa === 2)                               /* wsbh */
                    r[rd] = ((v & 0xff00ff00) >>> 8) | ((v & 0x00ff00ff) << 8);
                else fault('unimplemented SPECIAL3 bshfl ' + sa, undefined, inst, pc);
                break;
            }
            default:
                fault('unimplemented SPECIAL3 funct ' + fn, undefined, inst, pc);
                return;
            }
            break;
        }

        /* ============================================================ */
        /* loads                                                        */
        /* ============================================================ */
        case 32: {                                      /* lb */
            const a = (r[rs] + simm) | 0;
            r[rt] = (M[a] << 24) >> 24;
            break;
        }
        case 33: {                                      /* lh */
            const a = (r[rs] + simm) | 0;
            r[rt] = ((M[a] | (M[a + 1] << 8)) << 16) >> 16;
            break;
        }
        case 34: {                                      /* lwl (little endian) */
            const a = (r[rs] + simm) | 0;
            const n = a & 3;
            const w = (M[a - n] | (M[a - n + 1] << 8) | (M[a - n + 2] << 16) | (M[a - n + 3] << 24)) | 0;
            const sh = 8 * (3 - n);
            const v = (w << sh) | (r[rt] & ((1 << sh) - 1));
            r[rt] = v | 0;
            break;
        }
        case 35: {                                      /* lw */
            const a = (r[rs] + simm) | 0;
            r[rt] = (M[a] | (M[a + 1] << 8) | (M[a + 2] << 16) | (M[a + 3] << 24)) | 0;
            break;
        }
        case 36: {                                      /* lbu */
            const a = (r[rs] + simm) | 0;
            r[rt] = M[a];
            break;
        }
        case 37: {                                      /* lhu */
            const a = (r[rs] + simm) | 0;
            r[rt] = M[a] | (M[a + 1] << 8);
            break;
        }
        case 38: {                                      /* lwr (little endian) */
            const a = (r[rs] + simm) | 0;
            const n = a & 3;
            const w = (M[a - n] | (M[a - n + 1] << 8) | (M[a - n + 2] << 16) | (M[a - n + 3] << 24)) | 0;
            const mask = (-1) >>> (8 * n);
            r[rt] = ((r[rt] & ~mask) | ((w >>> (8 * n)) & mask)) | 0;
            break;
        }
        case 48: {                                      /* ll */
            const a = (r[rs] + simm) | 0;
            r[rt] = (M[a] | (M[a + 1] << 8) | (M[a + 2] << 16) | (M[a + 3] << 24)) | 0;
            break;
        }

        /* ============================================================ */
        /* stores                                                       */
        /* ============================================================ */
        case 40: {                                      /* sb */
            const a = (r[rs] + simm) | 0;
            M[a] = r[rt] & 0xff;
            break;
        }
        case 41: {                                      /* sh */
            const a = (r[rs] + simm) | 0;
            const v = r[rt];
            M[a] = v & 0xff;
            M[a + 1] = (v >>> 8) & 0xff;
            break;
        }
        case 42: {                                      /* swl (little endian) */
            const a = (r[rs] + simm) | 0;
            const n = a & 3;
            const base = a - n;
            const sh = 8 * (3 - n);
            const mask = (-1) >>> sh;
            const old = (M[base] | (M[base + 1] << 8) | (M[base + 2] << 16) | (M[base + 3] << 24)) >>> 0;
            const nw = ((old & ~mask) >>> 0) | (((r[rt] >>> sh) & mask) >>> 0);
            M[base] = nw & 0xff;
            M[base + 1] = (nw >>> 8) & 0xff;
            M[base + 2] = (nw >>> 16) & 0xff;
            M[base + 3] = (nw >>> 24) & 0xff;
            break;
        }
        case 43: {                                      /* sw */
            const a = (r[rs] + simm) | 0;
            const v = r[rt];
            M[a] = v & 0xff;
            M[a + 1] = (v >>> 8) & 0xff;
            M[a + 2] = (v >>> 16) & 0xff;
            M[a + 3] = (v >>> 24) & 0xff;
            break;
        }
        case 46: {                                      /* swr (little endian) */
            const a = (r[rs] + simm) | 0;
            const n = a & 3;
            const base = a - n;
            const mask = ((-1) >>> (8 * n)) >>> 0;
            const old = (M[base] | (M[base + 1] << 8) | (M[base + 2] << 16) | (M[base + 3] << 24)) >>> 0;
            const nw = ((old & ~mask) >>> 0) | (((r[rt] << (8 * n)) & mask) >>> 0);
            M[base] = nw & 0xff;
            M[base + 1] = (nw >>> 8) & 0xff;
            M[base + 2] = (nw >>> 16) & 0xff;
            M[base + 3] = (nw >>> 24) & 0xff;
            break;
        }
        case 56: {                                      /* sc */
            const a = (r[rs] + simm) | 0;
            const v = r[rt];
            M[a] = v & 0xff;
            M[a + 1] = (v >>> 8) & 0xff;
            M[a + 2] = (v >>> 16) & 0xff;
            M[a + 3] = (v >>> 24) & 0xff;
            r[rt] = 1;
            break;
        }

        /* ============================================================ */
        /* COP1 - floating point                                        */
        /* ============================================================ */
        case 17: {                                      /* COP1 */
            const fsub = (inst >>> 21) & 31;
            if (fsub === 8) {                           /* bc1f/bc1t */
                const cc = (inst >>> 18) & 7;
                const tf = (inst >>> 16) & 1;
                if ((fccL[cc] === tf)) NEXT_PC = (PC + (simm << 2)) | 0;
                break;
            }
            const fs = (inst >>> 11) & 31;
            const fd = (inst >>> 6) & 31;
            const fn = inst & 63;
            switch (fsub) {
            case 0:                                     /* mfc1 */
                r[rt] = fuL[fs];
                break;
            case 1:                                     /* mfhc1 */
                r[rt] = fuL[fs | 1];
                break;
            case 4:                                     /* mtc1 */
                fuL[fs] = r[rt] | 0;
                break;
            case 5:                                     /* mfhc1 (alt encoding) */
                r[rt] = fuL[fs | 1];
                break;
            case 6:                                     /* ctc1 */
                break;
            case 7:                                     /* mthc1 */
                fuL[fs | 1] = r[rt] | 0;
                break;
            case 16: {                                  /* S */
                const a = ffL[fs], b = ffL[rt];
                switch (fn) {
                case 0:  ffL[fd] = Math.fround(a + b); break;
                case 1:  ffL[fd] = Math.fround(a - b); break;
                case 2:  ffL[fd] = Math.fround(a * b); break;
                case 3:  ffL[fd] = Math.fround(a / b); break;
                case 4:  ffL[fd] = Math.fround(Math.sqrt(a)); break;
                case 5:  ffL[fd] = Math.abs(a); break;
                case 6:  ffL[fd] = a; break;                       /* mov.s */
                case 7:  ffL[fd] = -a; break;
                case 13: fuL[fd] = truncW(a); break;               /* trunc.w.s */
                case 12: fuL[fd] = roundW(a); break;
                case 14: fuL[fd] = truncW(Math.ceil(a)); break;
                case 15: fuL[fd] = truncW(Math.floor(a)); break;
                case 17: {                                         /* movt/movf */
                    const cc = (inst >>> 8) & 7, tf = (inst >>> 16) & 1;
                    if (fccL[cc] === tf) ffL[fd] = a;
                    break;
                }
                case 18: if (r[rt] === 0) ffL[fd] = a; break;      /* movz.s */
                case 19: if (r[rt] !== 0) ffL[fd] = a; break;      /* movn.s */
                case 32: ffL[fd] = Math.fround(a); break;          /* cvt.s.s */
                case 33: fwL[fd >> 1] = a; break;                  /* cvt.d.s */
                case 36: fuL[fd] = truncW(a); break;               /* cvt.w.s */
                default:
                    if (fn >= 48 && fn < 64) {                     /* c.cond.s */
                        const cc = (inst >>> 8) & 7;
                        const cond = fn & 15;
                        const un = (a !== a) || (b !== b);
                        fccL[cc] = (((cond & 1) && un) ||
                                    ((cond & 4) && !un && a < b) ||
                                    ((cond & 2) && !un && a === b)) ? 1 : 0;
                    } else {
                        fault('unimplemented COP1.S funct ' + fn, undefined, inst, pc);
                        return;
                    }
                }
                break;
            }
            case 17: {                                  /* D */
                const a = fwL[fs >> 1], b = fwL[rt >> 1];
                switch (fn) {
                case 0:  fwL[fd >> 1] = a + b; break;
                case 1:  fwL[fd >> 1] = a - b; break;
                case 2:  fwL[fd >> 1] = a * b; break;
                case 3:  fwL[fd >> 1] = a / b; break;
                case 4:  fwL[fd >> 1] = Math.sqrt(a); break;
                case 5:  fwL[fd >> 1] = Math.abs(a); break;
                case 6:  fwL[fd >> 1] = a; break;                  /* mov.d */
                case 7:  fwL[fd >> 1] = -a; break;
                case 13: fuL[fd] = truncW(a); break;
                case 12: fuL[fd] = roundW(a); break;
                case 17: {                                         /* movt/movf */
                    const cc = (inst >>> 8) & 7, tf = (inst >>> 16) & 1;
                    if (fccL[cc] === tf) fwL[fd >> 1] = a;
                    break;
                }
                case 32: ffL[fd] = Math.fround(a); break;          /* cvt.s.d */
                case 36: fuL[fd] = truncW(a); break;
                default:
                    if (fn >= 48 && fn < 64) {
                        const cc = (inst >>> 8) & 7;
                        const cond = fn & 15;
                        const un = (a !== a) || (b !== b);
                        fccL[cc] = (((cond & 1) && un) ||
                                    ((cond & 4) && !un && a < b) ||
                                    ((cond & 2) && !un && a === b)) ? 1 : 0;
                    } else {
                        fault('unimplemented COP1.D funct ' + fn, undefined, inst, pc);
                        return;
                    }
                }
                break;
            }
            case 20: {                                  /* W */
                const a = fuL[fs] | 0, b = fuL[rt] | 0;
                switch (fn) {
                case 32: ffL[fd] = Math.fround(a); break;          /* cvt.s.w */
                case 33: fwL[fd >> 1] = a; break;                  /* cvt.d.w */
                default:
                    fault('unimplemented COP1.W funct ' + fn, undefined, inst, pc);
                    return;
                }
                break;
            }
            default:
                fault('unimplemented COP1 fmt ' + fsub, undefined, inst, pc);
                return;
            }
            break;
        }

        case 49: {                                      /* lwc1 */
            const a = (r[rs] + simm) | 0;
            fu[(inst >>> 16) & 31] = (M[a] | (M[a + 1] << 8) | (M[a + 2] << 16) | (M[a + 3] << 24)) | 0;
            break;
        }
        case 53: {                                      /* ldc1 */
            const a = (r[rs] + simm) | 0;
            const ft = (inst >>> 16) & 31;
            fu[ft] = (M[a] | (M[a + 1] << 8) | (M[a + 2] << 16) | (M[a + 3] << 24)) | 0;
            fu[ft | 1] = (M[a + 4] | (M[a + 5] << 8) | (M[a + 6] << 16) | (M[a + 7] << 24)) | 0;
            break;
        }
        case 57: {                                      /* swc1 */
            const a = (r[rs] + simm) | 0;
            const v = fu[(inst >>> 16) & 31];
            M[a] = v & 0xff; M[a + 1] = (v >>> 8) & 0xff;
            M[a + 2] = (v >>> 16) & 0xff; M[a + 3] = (v >>> 24) & 0xff;
            break;
        }
        case 61: {                                      /* sdc1 */
            const a = (r[rs] + simm) | 0;
            const ft = (inst >>> 16) & 31;
            let v = fu[ft];
            M[a] = v & 0xff; M[a + 1] = (v >>> 8) & 0xff;
            M[a + 2] = (v >>> 16) & 0xff; M[a + 3] = (v >>> 24) & 0xff;
            v = fu[ft | 1];
            M[a + 4] = v & 0xff; M[a + 5] = (v >>> 8) & 0xff;
            M[a + 6] = (v >>> 16) & 0xff; M[a + 7] = (v >>> 24) & 0xff;
            break;
        }

        case 51:                                        /* pref */
            break;
        case 47: case 55: case 59: case 63:             /* cache/ld/... */
            fault('unimplemented opcode ' + op, undefined, inst, pc);
            return;

        default:
            fault('unimplemented opcode ' + op, undefined, inst, pc);
            return;
        }

        /* ---------------- periodic housekeeping ---------------- */
        if (icnt >= nextCheck) {
            instrCount = icnt;
            nextCheck = icnt + (1 << 20);
            const now = Date.now();
            if (now - lastReport > 1000) {
                lastReport = now;
                if (!OPT.quiet) {
                    const secs = (now - startTime) / 1000;
                    process.stderr.write('[vm] ' + (icnt / 1e6).toFixed(0) + 'M instr, ' +
                        secs.toFixed(0) + 's, ' + (icnt / secs / 1e6).toFixed(0) +
                        'M instr/s, frames: ' + framesSaved + '\r');
                }
            }
            if (OPT.maxSeconds && now - startTime > OPT.maxSeconds * 1000) {
                process.stderr.write('\n[vm] time limit reached\n');
                instrCount = icnt;
                shutdown(0);
                return;
            }
            if (OPT.maxFrames && framesSaved >= OPT.maxFrames) {
                process.stderr.write('\n[vm] frame limit reached\n');
                instrCount = icnt;
                shutdown(0);
                return;
            }
        }
    }
}
