/* ------------------------------------------------------------------ */
/*  guest program startup                                              */
/* ------------------------------------------------------------------ */

let exited = false;

const origShutdown = shutdown;
shutdown = function (code) {
    if (exited) return;
    exited = true;
    origShutdown(code);
};

function writeCString(addr, s) {
    for (let i = 0; i < s.length; i++) mem[addr + i] = s.charCodeAt(i) & 0xff;
    mem[addr + s.length] = 0;
}

function setupStack() {
    let sp = STACK_TOP - 512;

    /* argument strings */
    const progName = 'doomgeneric';
    writeCString(sp, progName);
    const arg0 = sp;
    const envStr = sp + 32;
    writeCString(envStr, 'DOOMWADDIR=.');
    sp += 128;
    sp &= ~7;

    /* argc, argv[], NULL, envp[], NULL, auxv (AT_NULL) */
    write32(sp + 0,  2);
    write32(sp + 4,  arg0);
    write32(sp + 8,  envStr);
    write32(sp + 12, 0);          /* end of argv   */
    write32(sp + 16, 0);          /* end of envp   */
    write32(sp + 20, 0);          /* AT_NULL       */
    write32(sp + 24, 0);

    R[29] = sp | 0;               /* $sp   */
    R[25] = entry_;               /* $t9   */
    R[31] = 0;                    /* $ra   */
    R[30] = sp | 0;               /* $fp   */
}

/* ------------------------------------------------------------------ */
/*  go!                                                                */
/* ------------------------------------------------------------------ */

const elfFile = findElf();
const elfInfo = loadElf(elfFile);
var entry_ = elfInfo.entry;

if (!OPT.framesDir) OPT.framesDir = defaultFramesDir();
try { fs.mkdirSync(OPT.framesDir, { recursive: true }); } catch (e) { }

log('[vm] MIPS interpreter starting');
log('[vm] executable : ' + elfFile);
log('[vm] entry      : 0x' + (entry_ >>> 0).toString(16));
log('[vm] memory top : 0x' + (elfInfo.top >>> 0).toString(16) +
    '  (' + (elfInfo.top / 1048576).toFixed(1) + ' MiB)');
log('[vm] frames dir : ' + OPT.framesDir);

setupStack();
try {
    run(entry_);
} catch (e) {
    process.stderr.write('\n[vm] fatal error: ' + e.stack + '\n');
    fault('internal error', undefined, 0, PC);
}
